using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using RoR2;
using UnityEngine;
using UnityEngine.AddressableAssets;
using Object = UnityEngine.Object;

namespace JakSurvivor
{
    // Jak's own item display rules, keyed by ItemDef, EquipmentDef or KeyItemDef name.
    // Generated by the DevTools exporter into Assets/JakSurvivor/ItemDisplays.
    [Serializable]
    internal sealed class JakItemDisplayData
    {
        // Core height as a fraction of the Head anchor height, both in the bind pose.
        public float coreHeight;
        public JakItemDisplayEntry[] entries = Array.Empty<JakItemDisplayEntry>();
    }

    [Serializable]
    internal sealed class JakItemDisplayEntry
    {
        public string key;
        public JakItemDisplayRule[] rules = Array.Empty<JakItemDisplayRule>();
    }

    [Serializable]
    internal sealed class JakItemDisplayRule
    {
        public ItemDisplayRuleType ruleType;
        public string childName;
        // Addressables GUID of the follower prefab.
        public string followerPrefab;
        public Vector3 localPos, localAngles, localScale;
        public LimbFlags limbMask;

        public ItemDisplayRule ToRule() => new ItemDisplayRule
        {
            ruleType = ruleType, childName = childName, localPos = localPos, localAngles = localAngles, localScale = localScale, limbMask = limbMask,
            followerPrefabAddress = string.IsNullOrEmpty(followerPrefab) ? null : new AssetReferenceGameObject(followerPrefab)
        };
    }

    // Anatomical anchor frames shared by the importer (Jak) and the exporter (Commando).
    // Measured in the skinning bind pose, where both rigs stand upright: up runs along the
    // limb or spine, forward leaves the front of the body, right is the body's right.
    internal static class JakItemAnatomy
    {
        public const string Base = "Base", Core = "Core";
        private static readonly Dictionary<string, (string From, string To)> Axes = new Dictionary<string, (string, string)>
        {
            ["Head"] = ("Pelvis", "Head"), ["Chest"] = ("Pelvis", "Head"), ["Pelvis"] = ("Pelvis", "Head"),
            ["UpperArmL"] = ("UpperArmL", "LowerArmL"), ["UpperArmR"] = ("UpperArmR", "LowerArmR"),
            ["LowerArmL"] = ("LowerArmL", "HandL"), ["LowerArmR"] = ("LowerArmR", "HandR"),
            ["HandL"] = ("LowerArmL", "HandL"), ["HandR"] = ("LowerArmR", "HandR"),
            ["ThighL"] = ("ThighL", "CalfL"), ["ThighR"] = ("ThighR", "CalfR"),
            ["CalfL"] = ("CalfL", "FootL"), ["CalfR"] = ("CalfR", "FootR"),
            ["FootL"] = ("CalfL", "FootL"), ["FootR"] = ("CalfR", "FootR")
        };

        public static IEnumerable<string> Anchors => Axes.Keys;

        // Rotation of an anchor's frame, from landmark positions in one space. Base is that space.
        public static Quaternion Frame(string anchor, Func<string, Vector3> at)
        {
            if (anchor == Base) return Quaternion.identity;
            Vector3 up = Axis(anchor, at);
            Vector3 right = at("UpperArmR") - at("UpperArmL") + at("ThighR") - at("ThighL");
            Vector3 forward = Vector3.Cross(right, at("Head") - at("Pelvis"));
            return Quaternion.LookRotation(Vector3.ProjectOnPlane(forward, up), up);
        }

        // The landmark an anchor's segment runs from, and the segment itself.
        public static string Root(string anchor) => Axes[anchor].From;

        public static Vector3 Axis(string anchor, Func<string, Vector3> at)
        {
            (string from, string to) = Axes[anchor];
            return at(to) - at(from);
        }
    }

    // Root-space matrices in the skinning bind pose, in live units. A transform that is not
    // a skinning bone keeps its current rigid offset from its nearest skinned ancestor.
    internal sealed class JakBindPose
    {
        private readonly Transform root;
        private readonly Dictionary<Transform, Matrix4x4> bones = new Dictionary<Transform, Matrix4x4>();
        private readonly Matrix4x4 units;

        public JakBindPose(Transform root)
        {
            this.root = root;
            // Daxter's rig has its own scale; counting it would shift Jak's units and every anchor.
            foreach (SkinnedMeshRenderer renderer in root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r => r.sharedMesh && !IsCompanion(r.transform)))
            {
                Matrix4x4[] binds = renderer.sharedMesh.bindposes;
                for (int i = 0; i < binds.Length; i++)
                    if (renderer.bones[i] && !bones.ContainsKey(renderer.bones[i])) bones.Add(renderer.bones[i], Local(renderer.transform) * binds[i].inverse);
            }
            // Jak's bind pose carries his native 1.4 body scale, which the live rig compensates.
            float[] ratios = bones.Select(p => Local(p.Key).lossyScale.x / p.Value.lossyScale.x).OrderBy(r => r).ToArray();
            units = Matrix4x4.Scale(Vector3.one * ratios[ratios.Length / 2]);
        }

        public bool IsBone(Transform node) => bones.ContainsKey(node);

        public bool IsCompanion(Transform node)
        {
            for (; node && node != root; node = node.parent)
                if (node.name == JakDaxter.ActorName) return true;
            return false;
        }

        public Matrix4x4 this[Transform node]
        {
            get
            {
                for (Transform bone = node; bone && bone != root; bone = bone.parent)
                    if (bones.TryGetValue(bone, out Matrix4x4 bind)) return units * bind * bone.worldToLocalMatrix * node.localToWorldMatrix;
                return Local(node);
            }
        }

        // Skinned mesh vertices are stored in the bind pose of their renderer's space.
        public Matrix4x4 Mesh(Renderer renderer) => units * Local(renderer.transform);

        private Matrix4x4 Local(Transform node) => root.worldToLocalMatrix * node.localToWorldMatrix;
    }

    internal static class JakItemDisplays
    {
        public const string DataAsset = "JakItemDisplays";
        public const string DataPath = "Assets/JakSurvivor/ItemDisplays/" + DataAsset + ".json";

        public static JakItemDisplayData Data { get; private set; }
        public static ItemDisplayRuleSet RuleSet { get; private set; }

        public static void Load()
        {
            Data = Parse(JakAssets.Get<TextAsset>(DataAsset).text);
            RuleSet = ScriptableObject.CreateInstance<ItemDisplayRuleSet>();
            RuleSet.name = "idrsJak";
            RoR2Application.onLoad += () => Fill(RuleSet, Data);
        }

        public static JakItemDisplayData Parse(string json)
        {
            var data = JsonUtility.FromJson<JakItemDisplayData>(json);
            if (data == null || data.entries == null || !(data.coreHeight > 0f && data.coreHeight < 1f) ||
                data.entries.Any(e => string.IsNullOrEmpty(e.key) || e.rules == null || e.rules.Any(r => string.IsNullOrEmpty(r.childName) && r.ruleType == ItemDisplayRuleType.ParentedPrefab)))
                throw new InvalidDataException("Invalid Jak item display data.");
            return data;
        }

        // Key assets resolve through the catalogs, so this runs once they are ready.
        public static void Fill(ItemDisplayRuleSet set, JakItemDisplayData data)
        {
            var groups = new List<ItemDisplayRuleSet.KeyAssetRuleGroup>();
            foreach (JakItemDisplayEntry entry in data.entries)
            {
                Object key = KeyAsset(entry.key);
                if (!key) { Plugin.Log.LogWarning("No catalog definition for Jak item display " + entry.key + "."); continue; }
                groups.Add(new ItemDisplayRuleSet.KeyAssetRuleGroup { keyAsset = key, displayRuleGroup = new DisplayRuleGroup { rules = entry.rules.Select(r => r.ToRule()).ToArray() } });
            }
            set.keyAssetRuleGroups = groups.ToArray();
            for (var generate = set.GenerateRuntimeValuesAsync(); generate.MoveNext();) { }
        }

        public static Object KeyAsset(string name)
        {
            ItemIndex item = ItemCatalog.FindItemIndex(name);
            if (item != ItemIndex.None) return ItemCatalog.GetItemDef(item);
            EquipmentIndex equipment = EquipmentCatalog.FindEquipmentIndex(name);
            if (equipment != EquipmentIndex.None) return EquipmentCatalog.GetEquipmentDef(equipment);
            KeyItemIndex keyItem = KeyItemCatalog.FindKeyItemIndex(name);
            return keyItem != KeyItemIndex.None ? KeyItemCatalog.GetKeyItemDef(keyItem) : null;
        }
    }
}
